microbenchmark.source:
//! Disposable benchmark of the existing raw Id allocation operation.
#[path = "../tests/support/oop.rs"] mod oop;
use birnam_abi::{Oop,size,as_size};
unsafe extern "C" { fn clock_gettime_nsec_np(clock:u32)->u64; }
fn main(){
 let h=oop::bootstrap();let q=h.scope();let gc=h.named(b"GC").unwrap();
 // Name's existing no-reference owner permits zeroed raw bytes of any extent.
 let behavior=q.call(h.id.root,b"nameBehavior",&[]).unwrap();
 let key=|n:&[u8]|q.keep(h.intern(n).unwrap()).unwrap();
 let allocate=key(b"allocate:bytes:");let extent=key(b"allocationSizeOf:");let vtable=key(b"behaviorOf:");let identity=key(b"identityOf:");
 assert!(unsafe{h.id.send(h.id.root,allocate,&[std::ptr::null_mut(),size(0).unwrap()])}.is_err());
 for bytes in [0,24,256] {
  let args=[behavior,size(bytes).unwrap()];let count=32768;
  for sample in 0..7 {
   q.call(gc,b"collectPrecisely",&[]).unwrap();
   let mut values:Vec<Oop>=Vec::with_capacity(count);
   let start=unsafe{clock_gettime_nsec_np(16)};
   for _ in 0..count { values.push(unsafe{h.id.send(h.id.root,allocate,&args).unwrap()}); }
   let elapsed=unsafe{clock_gettime_nsec_np(16)}-start;
   let mut previous=0;
   for value in values {
    assert_eq!(unsafe{h.id.send(h.id.root,vtable,&[value]).unwrap()},behavior);
    assert_eq!(as_size(unsafe{h.id.send(h.id.root,extent,&[value]).unwrap()}),Some(bytes));
    let id=as_size(unsafe{h.id.send(h.id.root,identity,&[value]).unwrap()}).unwrap();assert!(id>previous);previous=id;
   }
   println!("{bytes} {sample} {count} {elapsed}");
  }
 }
}

broader_probes.source:
[System println: "CASE integer-loop"];
[Module load: #time];
[[|

let operation := [| [1 to: 500 do: [:i | nil]]];
let result := [operation value];
[[result = 1] ifFalse: [| [System println: "PERF_BAD"]]];
[1 to: 3 do: [:sample |
  [System gc];
  let startedCpu := [16 clockNanos]; let startedWall := [6 clockNanos];
  [operation value];
  let endedWall := [6 clockNanos]; let endedCpu := [16 clockNanos];
  [System println: [endedCpu - startedCpu]];
  [System println: [endedWall - startedWall]]
]];
[System println: "PERF_OK"]
] value]

[System println: "CASE range-loop"];
[Module load: #time];
[[|
let range := [1 to: 500];
let operation := [| [range do: [:i | nil]]];
let result := [operation value];
[[result == range] ifFalse: [| [System println: "PERF_BAD"]]];
[1 to: 3 do: [:sample |
  [System gc];
  let startedCpu := [16 clockNanos]; let startedWall := [6 clockNanos];
  [operation value];
  let endedWall := [6 clockNanos]; let endedCpu := [16 clockNanos];
  [System println: [endedCpu - startedCpu]];
  [System println: [endedWall - startedWall]]
]];
[System println: "PERF_OK"]
] value]

[System println: "CASE method-loop"];
[Module load: #time];
[[|
let target := [Object clone]; [Reflect defineMethod: #perfEcho: on: target as: [:self :argument | argument]];
let operation := [| [1 to: 500 do: [:i | [target perfEcho: i]]]];
let result := [operation value];
[[result = 1] ifFalse: [| [System println: "PERF_BAD"]]];
[1 to: 3 do: [:sample |
  [System gc];
  let startedCpu := [16 clockNanos]; let startedWall := [6 clockNanos];
  [operation value];
  let endedWall := [6 clockNanos]; let endedCpu := [16 clockNanos];
  [System println: [endedCpu - startedCpu]];
  [System println: [endedWall - startedWall]]
]];
[System println: "PERF_OK"]
] value]

